<?php use Aibid\Http\View as V; ?>
<section class="panel form-panel mt-4"><h2>Información administrativa</h2><p class="small text-secondary">Actualizar estos campos no cambia código, archivo firmado, derechos, vigencia ni activaciones.</p>
<?php if ($actor->canWrite()): ?><form class="stack-form" method="post" action="/admin/licenses/<?= V::escape($licenseId) ?>/administrative"><?php V::fields($csrf); ?><input type="hidden" name="administrative_version" value="<?= (int)$license['administrative_version'] ?>">
<label>Referencia comercial <span class="optional">opcional</span><input class="form-control mt-2" name="reference" maxlength="190" value="<?= V::escape($license['commercial_reference']) ?>"></label>
<label>Motivo / nota de autorización <span class="optional">opcional</span><textarea class="form-control mt-2" name="reason" maxlength="500" rows="2"><?= V::escape($license['authorization_note']) ?></textarea></label><button class="btn btn-outline-primary">Guardar información administrativa</button></form>
<?php else: ?><p>Referencia: <?= V::escape($license['commercial_reference'] ?: 'Sin informar') ?></p><p>Nota: <?= V::escape($license['authorization_note'] ?: 'Sin informar') ?></p><?php endif; ?>
<?php if ($license['administrative_history']): ?><details class="mt-3"><summary>Historial administrativo</summary><?php foreach ($license['administrative_history'] as $change): ?><div class="note-box mt-2"><strong><?= $change['field_name']==='commercial_reference'?'Referencia comercial':'Nota de autorización' ?></strong><p>Anterior: <?= V::escape($change['old_value'] ?: '(vacío)') ?><br>Nuevo: <?= V::escape($change['new_value'] ?: '(vacío)') ?></p><small><?= V::escape($change['actor_name']) ?> · <?= V::escape(V::date($change['created_at'])) ?> · Revisión <?= (int)$change['version'] ?></small></div><?php endforeach; ?></details><?php endif; ?></section>
<section class="panel form-panel mt-4"><h2>Constancias y entregas</h2><p class="small text-secondary">Cada generación conserva una revisión documental inmutable. Una revisión nueva no altera las anteriores.</p>
<?php if ($actor->canWrite()): ?><form method="post" action="/admin/licenses/<?= V::escape($licenseId) ?>/documents"><?php V::fields($csrf); ?><input type="hidden" name="document_type" value="licensing"><button class="btn btn-outline-primary">Generar constancia de licenciamiento</button><p class="small text-secondary mt-2">Documento administrativo sin código ni archivo de activación.</p></form><?php endif; ?>
<?php if ($actor->allows('documents.delivery')): ?><details class="mt-3"><summary>Generar constancia de activación y entrega</summary><form class="stack-form mt-3" method="post" action="/admin/licenses/<?= V::escape($licenseId) ?>/documents"><?php V::fields($csrf); ?><input type="hidden" name="document_type" value="delivery">
<label>Método<select class="form-select mt-2" name="activation_method"><?php if ($actor->allows('credentials.reveal')): ?><option value="online">Online · contiene código secreto</option><?php endif; ?><?php if ($actor->allows('offline.download') && $license['revisions']): ?><option value="offline">Offline · identifica el archivo firmado</option><?php endif; ?></select></label>
<label>Archivo firmado <span class="optional">solo para offline</span><select class="form-select mt-2" name="revision_id"><option value="">Selecciona una revisión</option><?php foreach ($license['revisions'] as $revision): ?><option value="<?= V::escape($revision['id_text']) ?>">Revisión <?= (int)$revision['license_revision'] ?> · <?= V::escape($revision['license_status']) ?></option><?php endforeach; ?></select></label>
<?php require __DIR__.'/reauth-fields.php'; ?><button class="btn btn-primary">Generar constancia de entrega</button></form></details><?php endif; ?>
<?php if (!$license['documents']): ?><p class="text-secondary small mt-3">No se han emitido constancias.</p><?php endif; ?>
<?php foreach ($license['documents'] as $doc): ?><div class="note-box mt-3"><strong><?= $doc['document_type']==='licensing'?'Constancia de licenciamiento':'Constancia de activación y entrega' ?> · r<?= (int)$doc['revision'] ?></strong><small class="cell-sub"><?= V::escape($doc['folio']) ?> · <?= V::escape(V::date($doc['generated_at'])) ?></small>
<?php if (($doc['document_type']==='licensing' && $actor->canWrite()) || ($actor->allows('documents.delivery') && (!$doc['contains_code'] || $actor->allows('credentials.reveal')) && (!$doc['contains_offline'] || $actor->allows('offline.download')))): ?><a class="text-link" href="/admin/documents/<?= V::escape($doc['id_text']) ?>/download">Descargar PDF r<?= (int)$doc['revision'] ?></a><?php endif; ?>
<?php if ($doc['offline_revision_text']!==null && $actor->allows('offline.download')): ?><br><a class="text-link" href="/admin/licenses/<?= V::escape($licenseId) ?>/revisions/<?= V::escape($doc['offline_revision_text']) ?>/download">Descargar archivo .lic de esta entrega</a><?php endif; ?></div><?php endforeach; ?></section>
